import React from "react";
import { clsx } from "clsx";

import { ListClasses } from "../list.styles";

export const ListToolbar = (props: React.HTMLAttributes<HTMLDivElement>) => {
  return <div {...props} className={clsx(ListClasses.toolbar, props.className)} />;
};

ListToolbar.displayName = "List.Toolbar";

export const ListToolbarTrailing = (props: React.HTMLAttributes<HTMLDivElement>) => {
  return <div {...props} className={clsx(ListClasses.toolbarTrailing, props.className)} />;
};

ListToolbarTrailing.displayName = "List.ToolbarTrailing";
